99	    agent?.adapterConfig && typeof agent.adapterConfig === "object"
100	      ? (agent.adapterConfig as Record<string, unknown>)
101	      : null;
102	
103	  const configCommand =
104	    typeof config?.command === "string" && config.command.length > 0 ? config.command : undefined;
105	  const agentCommand =
106	    typeof agentAdapterConfig?.command === "string" && agentAdapterConfig.command.length > 0
107	      ? agentAdapterConfig.command
108	      : undefined;
109	
110	  if (config && !config.hermesCommand && configCommand) {
111	    config.hermesCommand = configCommand;
112	  }
113	  if (agentAdapterConfig && !agentAdapterConfig.hermesCommand && agentCommand) {
114	    agentAdapterConfig.hermesCommand = agentCommand;
115	  }
116	
117	  return ctx;
118	}
